def list_projects(account_id, status=None, closed=None, public=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0320000" if __import__("os").path.isdir("./environment_mix/0320000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if account_id is None or not isinstance(account_id, str):
        return _err("VALIDATION_ERROR", "account_id is required and must be a string.")
    if not re.match(r"^ghacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is malformed.")
    if status is not None and (not isinstance(status, str) or status not in ("active", "archived")):
        return _err("VALIDATION_ERROR", "status must be one of: active, archived.")
    if closed is not None and not isinstance(closed, bool):
        return _err("VALIDATION_ERROR", "closed must be a boolean.")
    if public is not None and not isinstance(public, bool):
        return _err("VALIDATION_ERROR", "public must be a boolean.")
    if sort is not None and (not isinstance(sort, str) or sort not in ("created_at", "updated_at", "number", "title")):
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, number, title.")
    if order is not None and (not isinstance(order, str) or order not in ("asc", "desc")):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    accounts = _load("github_accounts.json")
    projects = _load("projects.json")
    conns = _load("github_auth_connections.json")
    logs = _load("tool_action_logs.json")

    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        # log failed
        log_id = "log_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        logs.append({
            "id": log_id,
            "account_id": account_id,
            "auth_connection_id": None,
            "project_id": None,
            "tool_name": "list_projects",
            "request_payload": {"account_id": account_id, "status": status, "closed": closed, "public": public, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
            "response_payload": {"error": {"code": "NOT_FOUND"}},
            "github_request_ids": None,
            "idempotency_key": None,
            "status": "failed",
            "error_message": "Account not found.",
            "created_at": now,
            "updated_at": now
        })
        _save("tool_action_logs.json", logs)
        return _err("NOT_FOUND", "Account not found.")

    # Ambient auth: pick a working active connection for this account if any; otherwise still allow read from cache.
    auth_conn = next((c for c in conns if c.get("account_id") == account_id and c.get("status") == "active" and isinstance(c.get("token_ciphertext"), str) and c.get("token_ciphertext").strip()), None)
    auth_connection_id = auth_conn.get("id") if auth_conn else None

    # Filter
    rows = [p for p in projects if p.get("account_id") == account_id and p.get("status") in ("active", "archived")]
    if status is not None:
        rows = [p for p in rows if p.get("status") == status]
    if closed is not None:
        rows = [p for p in rows if p.get("closed") is closed]
    if public is not None:
        rows = [p for p in rows if p.get("public") is public]

    # Sort
    sort_field = sort or "updated_at"
    sort_order = order or "desc"

    def _key(p):
        v = p.get(sort_field)
        if sort_field in ("created_at", "updated_at", "archived_at"):
            if isinstance(v, str):
                return v
            return ""
        if sort_field == "number":
            return v if isinstance(v, int) else -1
        if sort_field == "title":
            return (v or "").lower()
        return v

    rows.sort(key=_key, reverse=(sort_order == "desc"))

    # Cursor pagination: opaque cursor is base64(json({"o": offset}))
    offset = 0
    if cursor:
        try:
            payload = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(payload)
            if not isinstance(obj, dict) or "o" not in obj or not isinstance(obj["o"], int) or obj["o"] < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            offset = obj["o"]
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"o": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "projects": page,
        "page_info": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

    # Log
    log_id = "log_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    logs.append({
        "id": log_id,
        "account_id": account_id,
        "auth_connection_id": auth_connection_id,
        "project_id": None,
        "tool_name": "list_projects",
        "request_payload": {"account_id": account_id, "status": status, "closed": closed, "public": public, "sort": sort, "order": order, "limit": limit, "cursor": cursor},
        "response_payload": {"returned": len(page), "total": total, "has_more": has_more},
        "github_request_ids": [],
        "idempotency_key": None,
        "status": "succeeded",
        "error_message": None,
        "created_at": now,
        "updated_at": now
    })
    _save("tool_action_logs.json", logs)
    return resp

def create_project(account_id, title, short_description=None, public=None, **_extra):
    import json, os, datetime, re, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0320000" if __import__("os").path.isdir("./environment_mix/0320000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(22))

    def _gen_node_id():
        alphabet = string.ascii_letters + string.digits
        return "PVT_" + "".join(random.choice(alphabet) for _ in range(24))

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    t0 = time.time()

    # Validate
    if account_id is None or not isinstance(account_id, str):
        return _err("VALIDATION_ERROR", "account_id is required and must be a string.")
    if not re.match(r"^ghacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is malformed.")
    if title is None or not isinstance(title, str):
        return _err("VALIDATION_ERROR", "title is required and must be a string.")
    if len(title.strip()) < 1:
        return _err("VALIDATION_ERROR", "title must be non-empty.")
    if len(title) > 256:
        return _err("VALIDATION_ERROR", "title must be between 1 and 256 characters.")
    if short_description is not None and not isinstance(short_description, str):
        return _err("VALIDATION_ERROR", "short_description must be a string.")
    if public is not None and not isinstance(public, bool):
        return _err("VALIDATION_ERROR", "public must be a boolean.")

    accounts = _load("github_accounts.json")
    conns = _load("github_auth_connections.json")
    projects = _load("projects.json")
    logs = _load("tool_action_logs.json")

    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        log_id = "log_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        logs.append({
            "id": log_id,
            "account_id": account_id,
            "auth_connection_id": None,
            "project_id": None,
            "tool_name": "create_project",
            "request_payload": {"account_id": account_id, "title": title, "short_description": short_description, "public": public},
            "response_payload": {"error": {"code": "NOT_FOUND"}},
            "github_request_ids": None,
            "idempotency_key": None,
            "status": "failed",
            "error_message": "Account not found.",
            "created_at": now,
            "updated_at": now
        })
        _save("tool_action_logs.json", logs)
        return _err("NOT_FOUND", "Account not found.")

    # Need an active auth connection to create
    auth_conn = next((c for c in conns if c.get("account_id") == account_id and c.get("status") == "active" and isinstance(c.get("token_ciphertext"), str) and c.get("token_ciphertext").strip()), None)
    if not auth_conn:
        log_id = "log_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        logs.append({
            "id": log_id,
            "account_id": account_id,
            "auth_connection_id": None,
            "project_id": None,
            "tool_name": "create_project",
            "request_payload": {"account_id": account_id, "title": title, "short_description": short_description, "public": public},
            "response_payload": {"error": {"code": "UNAUTHORIZED"}},
            "github_request_ids": [],
            "idempotency_key": None,
            "status": "failed",
            "error_message": "No active auth connection available for this account.",
            "created_at": now,
            "updated_at": now
        })
        _save("tool_action_logs.json", logs)
        return _err("UNAUTHORIZED", "No active GitHub auth connection available to create projects for this account.")

    # Simulate GitHub API returning IDs and maybe a project number (monotonic local)
    existing_numbers = [p.get("number") for p in projects if p.get("account_id") == account_id and isinstance(p.get("number"), int)]
    next_number = (max(existing_numbers) + 1) if existing_numbers else 1

    # Enforce unique(account_id, number) and unique(github_node_id)
    if any(p for p in projects if p.get("account_id") == account_id and p.get("number") == next_number):
        # Extremely unlikely; bump until free
        cand = next_number
        while any(p for p in projects if p.get("account_id") == account_id and p.get("number") == cand):
            cand += 1
        next_number = cand

    github_node_id = _gen_node_id()
    # Ensure unique github_node_id
    tries = 0
    while any(p for p in projects if p.get("github_node_id") == github_node_id):
        github_node_id = _gen_node_id()
        tries += 1
        if tries > 10:
            return _err("CONFLICT", "Could not allocate a unique github_node_id.")

    project_id = _gen_id("ghproj")

    new_row = {
        "id": project_id,
        "account_id": account_id,
        "github_node_id": github_node_id,
        "number": next_number,
        "title": title,
        "short_description": short_description,
        "public": public,
        "closed": False,
        "status": "active",
        "archived_at": None,
        "created_at": now,
        "updated_at": now
    }

    projects.append(new_row)
    _save("projects.json", projects)

    resp = {"project": new_row}

    log_id = "log_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    logs.append({
        "id": log_id,
        "account_id": account_id,
        "auth_connection_id": auth_conn.get("id"),
        "project_id": project_id,
        "tool_name": "create_project",
        "request_payload": {"account_id": account_id, "title": title, "short_description": short_description, "public": public},
        "response_payload": {"project_id": project_id, "number": next_number},
        "github_request_ids": [],
        "idempotency_key": None,
        "status": "succeeded",
        "error_message": None,
        "created_at": now,
        "updated_at": now
    })
    _save("tool_action_logs.json", logs)

    _ = t0  # keep contract-friendly; latency not required in response
    return resp

def update_project_item(project_item_id, field_values=None, position=None, draft_title=None, draft_body=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0320000" if __import__("os").path.isdir("./environment_mix/0320000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        raw = os.urandom(12)
        s = base64.b32encode(raw).decode("ascii").rstrip("=")
        return f"{prefix}_{s}"

    def _log(account_id, auth_connection_id, project_id_for_log, ok, resp=None, err_msg=None):
        try:
            logs = _load("tool_action_logs.json")
            logs.append(
                {
                    "id": _new_id("ghlog"),
                    "account_id": account_id if account_id else "unknown",
                    "auth_connection_id": auth_connection_id,
                    "project_id": project_id_for_log,
                    "tool_name": "update_project_item",
                    "request_payload": {
                        "project_item_id": project_item_id,
                        "field_values": field_values,
                        "position": position,
                        "draft_title": draft_title,
                        "draft_body": draft_body,
                    },
                    "response_payload": resp,
                    "github_request_ids": None,
                    "idempotency_key": None,
                    "status": "succeeded" if ok else "failed",
                    "error_message": None if ok else (err_msg or "Request failed"),
                    "created_at": now,
                    "updated_at": now,
                }
            )
            _save("tool_action_logs.json", logs)
        except Exception:
            return

    try:
        if not isinstance(project_item_id, str) or not (
            re.match(r"^ghitem_[0-9A-Z]{18,}$", project_item_id) or re.match(r"^[A-Za-z0-9_:-]{6,}$", project_item_id)
        ):
            resp = _err("VALIDATION_ERROR", "project_item_id is malformed", field="project_item_id")
            _log(None, None, None, False, resp, resp["error"]["message"])
            return resp

        if field_values is not None and not isinstance(field_values, dict):
            resp = _err("VALIDATION_ERROR", "field_values must be an object", field="field_values")
            _log(None, None, None, False, resp, resp["error"]["message"])
            return resp
        if position is not None and not isinstance(position, (int, float)):
            resp = _err("VALIDATION_ERROR", "position must be a number", field="position")
            _log(None, None, None, False, resp, resp["error"]["message"])
            return resp
        if draft_title is not None and not isinstance(draft_title, str):
            resp = _err("VALIDATION_ERROR", "draft_title must be a string", field="draft_title")
            _log(None, None, None, False, resp, resp["error"]["message"])
            return resp
        if draft_body is not None and not isinstance(draft_body, str):
            resp = _err("VALIDATION_ERROR", "draft_body must be a string", field="draft_body")
            _log(None, None, None, False, resp, resp["error"]["message"])
            return resp

        if field_values is None and position is None and draft_title is None and draft_body is None:
            resp = _err("VALIDATION_ERROR", "At least one of field_values, position, draft_title, or draft_body must be provided")
            _log(None, None, None, False, resp, resp["error"]["message"])
            return resp

        items = _load("project_items.json")
        item = next((it for it in items if it.get("id") == project_item_id or it.get("github_node_id") == project_item_id), None)
        if not item:
            resp = _err("NOT_FOUND", "Project item not found")
            _log(None, None, None, False, resp, resp["error"]["message"])
            return resp

        project_id = item.get("project_id")
        projects = _load("projects.json")
        proj = next((p for p in projects if p.get("id") == project_id), None)
        if not proj:
            resp = _err("NOT_FOUND", "Project not found for this item")
            _log(None, None, project_id, False, resp, resp["error"]["message"])
            return resp

        account_id = proj.get("account_id")
        acct = next((a for a in _load("github_accounts.json") if a.get("id") == account_id), None)
        if not acct or acct.get("status") != "active":
            resp = _err("UNAUTHORIZED", "No active GitHub account available for this operation")
            _log(account_id, None, project_id, False, resp, resp["error"]["message"])
            return resp

        conns = _load("github_auth_connections.json")
        auth = next((c for c in conns if c.get("account_id") == account_id and c.get("status") == "active"), None)
        if not auth:
            resp = _err("UNAUTHORIZED", "No active GitHub auth connection available for this account")
            _log(account_id, None, project_id, False, resp, resp["error"]["message"])
            return resp

        if item.get("status") != "active":
            resp = _err("INVALID_TRANSITION", "Cannot update a project item that is not active")
            _log(account_id, auth.get("id"), project_id, False, resp, resp["error"]["message"])
            return resp

        if item.get("item_type") != "draft" and (draft_title is not None or draft_body is not None):
            resp = _err("VALIDATION_ERROR", "draft_title/draft_body may only be provided for draft items")
            _log(account_id, auth.get("id"), project_id, False, resp, resp["error"]["message"])
            return resp

        # Validate field_values against project_schema
        schema = _load("project_schema.json")
        active_fields = [s for s in schema if s.get("project_id") == project_id and s.get("entity_type") == "field" and s.get("status") == "active"]
        field_by_id = {f.get("id"): f for f in active_fields if f.get("id")}
        field_by_node = {f.get("github_node_id"): f for f in active_fields if f.get("github_node_id")}
        # options by parent_field_id (local id)
        active_options = [s for s in schema if s.get("project_id") == project_id and s.get("entity_type") == "field_option" and s.get("status") == "active"]
        options_by_parent = {}
        for o in active_options:
            pfid = o.get("parent_field_id")
            if pfid:
                options_by_parent.setdefault(pfid, []).append(o)

        def _resolve_field(key):
            if key in field_by_id:
                return field_by_id[key]
            if key in field_by_node:
                return field_by_node[key]
            return None

        def _validate_single_select_value(field_row, val):
            # Accept option by local option id, option github_node_id, or option name (case-sensitive).
            opts = options_by_parent.get(field_row.get("id"), [])
            if val is None:
                return True, None
            if isinstance(val, dict):
                # allow {"option_id": "..."} or {"id": "..."} or {"name": "..."}
                if "option_id" in val:
                    val = val["option_id"]
                elif "id" in val:
                    val = val["id"]
                elif "name" in val:
                    val = val["name"]
                else:
                    return False, "single_select value object must contain option_id/id/name"
            if not isinstance(val, str):
                return False, "single_select value must be a string (option id, option node id, or option name)"
            for o in opts:
                if val in (o.get("id"), o.get("github_node_id"), o.get("name")):
                    return True, None
            return False, "single_select value must reference an active field_option under the specified field"

        if field_values is not None:
            for k, v in field_values.items():
                frow = _resolve_field(k)
                if not frow:
                    resp = _err(
                        "VALIDATION_ERROR",
                        "field_values contains a field that is not an active project field",
                        field="field_values",
                        field_key=k,
                    )
                    _log(account_id, auth.get("id"), project_id, False, resp, resp["error"]["message"])
                    return resp
                if frow.get("field_data_type") == "single_select":
                    ok, msg = _validate_single_select_value(frow, v)
                    if not ok:
                        resp = _err("VALIDATION_ERROR", msg, field="field_values", field_key=k)
                        _log(account_id, auth.get("id"), project_id, False, resp, resp["error"]["message"])
                        return resp

        # Mutate
        changed = False
        if field_values is not None:
            current = item.get("field_values") if isinstance(item.get("field_values"), dict) else {}
            merged = dict(current)
            for k, v in field_values.items():
                merged[k] = v
            if merged != current:
                item["field_values"] = merged
                changed = True
        if position is not None and item.get("position") != position:
            item["position"] = position
            changed = True
        if draft_title is not None and item.get("draft_title") != draft_title:
            item["draft_title"] = draft_title
            changed = True
        if draft_body is not None and item.get("draft_body") != draft_body:
            item["draft_body"] = draft_body
            changed = True

        if not changed:
            resp = {"project_item": item}
            _log(account_id, auth.get("id"), project_id, True, {"project_item_id": item.get("id")})
            return resp

        item["updated_at"] = now
        _save("project_items.json", items)

        resp = {"project_item": item}
        _log(account_id, auth.get("id"), project_id, True, {"project_item_id": item.get("id")})
        return resp
    except Exception as e:
        resp = _err("CONFLICT", "Unexpected server error", detail=str(e))
        _log(None, None, None, False, resp, resp["error"]["message"])
        return resp

def list_project_fields(project_id, field_data_type=None, field_is_builtin=None, status=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0320000" if __import__("os").path.isdir("./environment_mix/0320000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        ts = int(datetime.datetime.utcnow().timestamp() * 1000)
        v = ts
        out = []
        while v > 0:
            v, r = divmod(v, 36)
            out.append(alphabet[r])
        s = "".join(reversed(out or ["0"]))
        s = (s + "0" * 18)[:18]
        return f"{prefix}_{s}"

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        # Accept opaque cursor from previous buggy implementations too: any non-empty string -> treat as 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            if raw.startswith("idx:"):
