def list_project_views(project_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0320000" if __import__("os").path.isdir("./environment_mix/0320000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        raw = os.urandom(12)
        s = base64.b32encode(raw).decode("ascii").rstrip("=")
        return f"{prefix}_{s}"

    def _log(account_id, auth_connection_id, ok, resp=None, err_msg=None):
        try:
            logs = _load("tool_action_logs.json")
            logs.append(
                {
                    "id": _new_id("ghlog"),
                    "account_id": account_id if account_id else "unknown",
                    "auth_connection_id": auth_connection_id,
                    "project_id": project_id,
                    "tool_name": "list_project_views",
                    "request_payload": {
                        "project_id": project_id,
                        "status": status,
                        "limit": limit,
                        "cursor": cursor,
                        "sort": sort,
                        "order": order,
                    },
                    "response_payload": resp,
                    "github_request_ids": None,
                    "idempotency_key": None,
                    "status": "succeeded" if ok else "failed",
                    "error_message": None if ok else (err_msg or "Request failed"),
                    "created_at": now,
                    "updated_at": now,
                }
            )
            _save("tool_action_logs.json", logs)
        except Exception:
            return

    def _encode_cursor(idx):
        raw = f"idx:{idx}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        # Accept either our encoded cursor or any opaque token by treating it as "start at 0"
        # unless it matches our format.
        try:
            pad = "=" * (-len(cur) % 4)
            b = base64.urlsafe_b64decode((cur + pad).encode("utf-8"))
            s = b.decode("utf-8", errors="ignore")
            if s.startswith("idx:"):
                return int(s.split(":", 1)[1])
        except Exception:
            return 0
        return 0

    try:
        if not isinstance(project_id, str) or not re.match(r"^ghproj_[0-9A-Z]{18,}$", project_id):
            resp = _err("VALIDATION_ERROR", "project_id is malformed", field="project_id")
            _log(None, None, False, resp, resp["error"]["message"])
            return resp

        if status is not None and status not in ("active", "deleted"):
            resp = _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "deleted"])
            _log(None, None, False, resp, resp["error"]["message"])
            return resp

        # Relax: if limit is provided above 100, clamp to 100 (real-world callers often over-ask).
        if limit is None:
            limit = 30
        if not isinstance(limit, int):
            resp = _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
            _log(None, None, False, resp, resp["error"]["message"])
            return resp
        if limit < 1:
            resp = _err("VALIDATION_ERROR", "limit must be >= 1", field="limit")
            _log(None, None, False, resp, resp["error"]["message"])
            return resp
        if limit > 100:
            limit = 100

        if sort is None:
            sort = "created_at"
        if sort not in ("created_at", "updated_at", "name"):
            resp = _err("VALIDATION_ERROR", "Invalid sort", field="sort", allowed=["created_at", "updated_at", "name"])
            _log(None, None, False, resp, resp["error"]["message"])
            return resp
        if order is None:
            order = "asc"
        if order not in ("asc", "desc"):
            resp = _err("VALIDATION_ERROR", "Invalid order", field="order", allowed=["asc", "desc"])
            _log(None, None, False, resp, resp["error"]["message"])
            return resp

        projects = _load("projects.json")
        proj = next((p for p in projects if p.get("id") == project_id), None)
        if not proj:
            resp = _err("NOT_FOUND", "Project not found")
            _log(None, None, False, resp, resp["error"]["message"])
            return resp

        account_id = proj.get("account_id")
        acct = next((a for a in _load("github_accounts.json") if a.get("id") == account_id), None)
        if not acct or acct.get("status") != "active":
            resp = _err("UNAUTHORIZED", "No active GitHub account available for this operation")
            _log(account_id, None, False, resp, resp["error"]["message"])
            return resp

        # For read operations, still require a workable active connection, but pick one that exists.
        auth = next((c for c in _load("github_auth_connections.json") if c.get("account_id") == account_id and c.get("status") == "active"), None)
        if not auth:
            resp = _err("UNAUTHORIZED", "No active GitHub auth connection available for this account")
            _log(account_id, None, False, resp, resp["error"]["message"])
            return resp

        schema = _load("project_schema.json")
        rows = [r for r in schema if r.get("project_id") == project_id and r.get("entity_type") == "view"]
        if status is not None:
            rows = [r for r in rows if r.get("status") == status]

        reverse = order == "desc"

        def _sort_key(r):
            v = r.get(sort)
            return (v is None, v)

        rows.sort(key=_sort_key, reverse=reverse)

        start = _decode_cursor(cursor)
        if start is None or start < 0:
            start = 0

        total = len(rows)
        page = rows[start : start + limit]
        next_idx = start + len(page)
        has_more = next_idx < total
        next_cursor = _encode_cursor(next_idx) if has_more else None

        resp = {
            "views": page,
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
        _log(account_id, auth.get("id"), True, {"returned": len(page), "total": total, "has_more": has_more})
        return resp
    except Exception as e:
        resp = _err("CONFLICT", "Unexpected server error", detail=str(e))
        _log(None, None, False, resp, resp["error"]["message"])
        return resp

