    elif not isinstance(limit, int):
        prjs = _load("projects.json")
        pr = next((p for p in prjs if p.get("id") == project_id), None)
        acct_id = pr.get("account_id") if pr else (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "unknown")
        _log(acct_id, None, project_id, {"project_id": project_id, "limit": limit}, {"error": "validation"}, False, "limit must be an integer")
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    else:
        limit_eff = max(1, min(100, limit))

    idx0 = _decode_cursor(cursor)
    if idx0 is None or idx0 < 0:
        prjs = _load("projects.json")
        pr = next((p for p in prjs if p.get("id") == project_id), None)
        acct_id = pr.get("account_id") if pr else (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "unknown")
        _log(acct_id, None, project_id, {"project_id": project_id, "cursor": cursor}, {"error": "validation"}, False, "cursor is invalid")
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    projects = _load("projects.json")
    project = next((p for p in projects if p.get("id") == project_id), None)
    if project is None:
        acct_id = (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "unknown")
        _log(acct_id, None, project_id, {"project_id": project_id}, {"error": "not_found"}, False, "Project not found")
        return _err("NOT_FOUND", "Project not found", resource="projects", id=project_id)

    account_id = project.get("account_id")
    auths = _load("github_auth_connections.json")
    auth_id = next((a.get("id") for a in auths if a.get("account_id") == account_id and a.get("status") == "active"), None)

    rows = [r for r in _load("project_items.json") if r.get("project_id") == project_id]
    if item_type is not None:
        rows = [r for r in rows if r.get("item_type") == item_type]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if repository_full_name is not None:
        rows = [r for r in rows if r.get("repository_full_name") == repository_full_name]
    if content_number is not None:
        rows = [r for r in rows if r.get("content_number") == content_number]
    if content_github_node_id is not None:
        rows = [r for r in rows if r.get("content_github_node_id") == content_github_node_id]

    sort_key = sort or "position"
    reverse = (order or "asc") == "desc"

    def _dt_or_min(s):
        if not isinstance(s, str):
            return datetime.datetime.min
        try:
            x = s[:-1] + "+00:00" if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return datetime.datetime.min

    def _pos_or_inf(v):
        try:
            return float(v)
        except Exception:
            return float("inf")

    if sort_key == "position":
        rows.sort(key=lambda r: (_pos_or_inf(r.get("position")), _dt_or_min(r.get("created_at")), r.get("id") or ""), reverse=reverse)
    elif sort_key in ("created_at", "updated_at"):
        rows.sort(key=lambda r: (_dt_or_min(r.get(sort_key)), r.get("id") or ""), reverse=reverse)

    total = len(rows)
    page = rows[idx0: idx0 + limit_eff]
    next_idx = idx0 + len(page)
    has_more = next_idx < total
    next_cursor = _encode_cursor(next_idx) if has_more else None

    resp = {
        "items": page,
        "total": total,
        "limit": limit_eff,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "latency_ms": int((time.time() - t0) * 1000),
    }
    _log(account_id, auth_id, project_id, {"project_id": project_id, "item_type": item_type, "status": status, "repository_full_name": repository_full_name, "content_number": content_number, "content_github_node_id": content_github_node_id, "limit": limit, "cursor": cursor, "sort": sort, "order": order}, {"total": total, "returned": len(page), "has_more": has_more}, True)
    return resp

def add_project_item(project_id, content_github_node_id, idempotency_key=None, field_values=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0320000" if __import__("os").path.isdir("./environment_mix/0320000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        ts = int(datetime.datetime.utcnow().timestamp() * 1000)
        v = ts
        out = []
        while v > 0:
            v, r = divmod(v, 36)
            out.append(alphabet[r])
        s = "".join(reversed(out or ["0"]))
        s = (s + "0" * 18)[:18]
        return f"{prefix}_{s}"

    def _log(account_id, auth_connection_id, project_id_for_log, req, resp, ok, err_msg=None):
        logs = _load("tool_action_logs.json")
        logs.append({
            "id": _new_id("ghlog"),
            "account_id": account_id,
            "auth_connection_id": auth_connection_id,
            "project_id": project_id_for_log,
            "tool_name": "add_project_item",
            "request_payload": req,
            "response_payload": resp,
            "github_request_ids": None,
            "idempotency_key": idempotency_key,
            "status": "succeeded" if ok else "failed",
            "error_message": None if ok else (err_msg or "Request failed"),
            "created_at": now,
            "updated_at": now,
        })
        _save("tool_action_logs.json", logs)

    # Validate
    if not isinstance(project_id, str) or not re.match(r"^ghproj_[0-9A-Z]{18,}$", project_id):
        acct_id = (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "unknown")
        _log(acct_id, None, project_id, {"project_id": project_id, "content_github_node_id": content_github_node_id, "idempotency_key": idempotency_key, "field_values": field_values}, {"error": "validation"}, False, "project_id is malformed")
        return _err("VALIDATION_ERROR", "project_id is malformed", field="project_id")
    if not isinstance(content_github_node_id, str) or not content_github_node_id.strip():
        prjs = _load("projects.json")
        pr = next((p for p in prjs if p.get("id") == project_id), None)
        acct_id = pr.get("account_id") if pr else (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "unknown")
        _log(acct_id, None, project_id, {"project_id": project_id, "content_github_node_id": content_github_node_id, "idempotency_key": idempotency_key, "field_values": field_values}, {"error": "validation"}, False, "content_github_node_id is required")
        return _err("VALIDATION_ERROR", "content_github_node_id is required", field="content_github_node_id")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        prjs = _load("projects.json")
        pr = next((p for p in prjs if p.get("id") == project_id), None)
        acct_id = pr.get("account_id") if pr else (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "unknown")
        _log(acct_id, None, project_id, {"project_id": project_id, "content_github_node_id": content_github_node_id, "idempotency_key": idempotency_key, "field_values": field_values}, {"error": "validation"}, False, "idempotency_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string", field="idempotency_key")
    if field_values is not None and not isinstance(field_values, dict):
        prjs = _load("projects.json")
        pr = next((p for p in prjs if p.get("id") == project_id), None)
        acct_id = pr.get("account_id") if pr else (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "unknown")
        _log(acct_id, None, project_id, {"project_id": project_id, "content_github_node_id": content_github_node_id, "idempotency_key": idempotency_key, "field_values": field_values}, {"error": "validation"}, False, "field_values must be an object")
        return _err("VALIDATION_ERROR", "field_values must be an object", field="field_values")

    projects = _load("projects.json")
    project = next((p for p in projects if p.get("id") == project_id), None)
    if project is None:
        acct_id = (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "unknown")
        _log(acct_id, None, project_id, {"project_id": project_id, "content_github_node_id": content_github_node_id, "idempotency_key": idempotency_key, "field_values": field_values}, {"error": "not_found"}, False, "Project not found")
        return _err("NOT_FOUND", "Project not found", resource="projects", id=project_id)

    account_id = project.get("account_id")
    auths = _load("github_auth_connections.json")
    auth_id = next((a.get("id") for a in auths if a.get("account_id") == account_id and a.get("status") == "active"), None)

    # Idempotency via tool_action_logs unique(idempotency_key, tool_name)
    if idempotency_key is not None:
        logs = _load("tool_action_logs.json")
        prior = next((l for l in logs if l.get("tool_name") == "add_project_item" and l.get("idempotency_key") == idempotency_key), None)
        if prior and prior.get("status") == "succeeded":
            resp = prior.get("response_payload")
            if isinstance(resp, dict) and "item" in resp:
                _log(account_id, auth_id, project_id, {"project_id": project_id, "content_github_node_id": content_github_node_id, "idempotency_key": idempotency_key, "field_values": field_values}, {"replayed": True}, True)
                return resp
            # fall through if malformed prior payload

    # Derived uniqueness: unique(project_id, content_github_node_id) among active items
    items = _load("project_items.json")
    dup = next((it for it in items if it.get("project_id") == project_id and it.get("status") == "active" and it.get("content_github_node_id") == content_github_node_id), None)
    if dup is not None:
        resp = {"item": dup, "created": False}
        _log(account_id, auth_id, project_id, {"project_id": project_id, "content_github_node_id": content_github_node_id, "idempotency_key": idempotency_key, "field_values": field_values}, {"item_id": dup.get("id"), "created": False, "latency_ms": int((time.time() - t0) * 1000)}, True)
        return resp

    # Determine issue vs PR heuristically: if repo has /pull/ in node id? not available; default "issue"
    item_type = "issue"

    # Validate field_values against active schema
    schema = _load("project_schema.json")
    fields = {f.get("id"): f for f in schema if f.get("project_id") == project_id and f.get("entity_type") == "field" and f.get("status") == "active"}
    options_by_parent = {}
    for opt in schema:
        if opt.get("project_id") == project_id and opt.get("entity_type") == "field_option" and opt.get("status") == "active" and opt.get("parent_field_id"):
            options_by_parent.setdefault(opt.get("parent_field_id"), set()).add(opt.get("id"))

    if field_values:
        for k, v in field_values.items():
            if k not in fields:
                _log(account_id, auth_id, project_id, {"project_id": project_id, "content_github_node_id": content_github_node_id, "idempotency_key": idempotency_key, "field_values": field_values}, {"error": "validation"}, False, f"field_values contains unknown or inactive field_id: {k}")
                return _err("VALIDATION_ERROR", f"field_values contains unknown or inactive field_id: {k}", field="field_values", rule="field must exist and be active for project")
            f = fields[k]
            if f.get("field_data_type") == "single_select":
                if not isinstance(v, str) or not v:
                    _log(account_id, auth_id, project_id, {"project_id": project_id, "content_github_node_id": content_github_node_id, "idempotency_key": idempotency_key, "field_values": field_values}, {"error": "validation"}, False, f"single_select field '{k}' requires option id string")
                    return _err("VALIDATION_ERROR", f"single_select field '{k}' requires option id string", field="field_values")
                if v not in options_by_parent.get(k, set()):
                    _log(account_id, auth_id, project_id, {"project_id": project_id, "content_github_node_id": content_github_node_id, "idempotency_key": idempotency_key, "field_values": field_values}, {"error": "validation"}, False, f"single_select value '{v}' is not an active option for field '{k}'")
                    return _err("VALIDATION_ERROR", f"single_select value '{v}' is not an active option for field '{k}'", field="field_values", rule="single_select values must reference active field_option under the field")

    # Create new project item
    new_item = {
        "id": _new_id("ghitem"),
        "project_id": project_id,
        "github_node_id": "PVTI_" + _new_id("N")[2:],  # opaque-ish stable id
        "item_type": item_type,
        "content_github_node_id": content_github_node_id,
        "repository_full_name": None,
        "content_number": None,
        "draft_title": None,
        "draft_body": None,
        "field_values": field_values or {},
        "position": None,
        "status": "active",
        "removed_at": None,
        "created_at": now,
        "updated_at": now,
    }
    items.append(new_item)
    _save("project_items.json", items)

    resp = {"item": new_item, "created": True, "latency_ms": int((time.time() - t0) * 1000)}
    _log(account_id, auth_id, project_id, {"project_id": project_id, "content_github_node_id": content_github_node_id, "idempotency_key": idempotency_key, "field_values": field_values}, {"item_id": new_item.get("id"), "created": True}, True)
    return resp

