    _log(account_id, auth_id, project_id, {"project_id": project_id, "draft_title": draft_title, "draft_body": draft_body, "field_values": field_values, "idempotency_key": idempotency_key}, {"item_id": new_item.get("id"), "created": True}, True)
    return resp

def create_task(project_id, mode, title, body=None, repository_full_name=None, field_values=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0320000" if __import__("os").path.isdir("./environment_mix/0320000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(random.choice(alphabet) for _ in range(20))

    def _log_resp(account_id, auth_connection_id, project_id_for_log, tool_name, request_payload, resp, status, error_message=None):
        logs = _load("tool_action_logs.json")
        if idempotency_key is not None:
            for row in logs:
                if row.get("tool_name") == tool_name and row.get("idempotency_key") == idempotency_key:
                    prior = row.get("response_payload")
                    if isinstance(prior, dict):
                        return prior
                    return resp
        log_row = {
            "id": _new_id("ghlog"),
            "account_id": account_id,
            "auth_connection_id": auth_connection_id,
            "project_id": project_id_for_log,
            "tool_name": tool_name,
            "request_payload": request_payload,
            "response_payload": resp if isinstance(resp, dict) else {"result": resp},
            "github_request_ids": None,
            "idempotency_key": idempotency_key,
            "status": status,
            "error_message": error_message if status == "failed" else None,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(log_row)
        _save("tool_action_logs.json", logs)
        return resp

    def _validate_field_values(project_id, fv):
        if fv is None:
            return (True, None, None)
        if not isinstance(fv, dict):
            return (False, _err("VALIDATION_ERROR", "field_values must be an object when provided."), "Invalid field_values.")
        schema = _load("project_schema.json")
        fields_by_id = {}
        fields_by_node = {}
        options_by_parent = {}
        for r in schema:
            if r.get("project_id") != project_id or r.get("status") != "active":
                continue
            if r.get("entity_type") == "field":
                fields_by_id[r.get("id")] = r
                fields_by_node[r.get("github_node_id")] = r
            elif r.get("entity_type") == "field_option":
                options_by_parent.setdefault(r.get("parent_field_id"), []).append(r)

        for k, v in fv.items():
            field = fields_by_id.get(k) or fields_by_node.get(k)
            if not field:
                return (False, _err("VALIDATION_ERROR", f"Unknown or inactive field in field_values: {k}."), f"Unknown field {k}.")
            ftype = field.get("field_data_type")
            if ftype == "single_select":
                # accept option id, option github_node_id, or option name (unique within field options not guaranteed; choose first)
                opts = options_by_parent.get(field.get("id"), [])
                if not opts:
                    return (False, _err("VALIDATION_ERROR", f"Field '{field.get('name')}' has no active options."), "Invalid single_select option.")
                ok = False
                if isinstance(v, str):
                    for o in opts:
                        if v in (o.get("id"), o.get("github_node_id"), o.get("name")):
                            ok = True
                            break
                if not ok:
                    return (False, _err("VALIDATION_ERROR", f"Invalid single_select value for field '{field.get('name')}'."), "Invalid single_select option.")
            else:
                # basic type acceptance: allow scalars/objects; leave as-is
                pass
        return (True, None, None)

    accounts = _load("github_accounts.json")
    conns = _load("github_auth_connections.json")
    projects = _load("projects.json")
    items = _load("project_items.json")

    active_accounts = {a["id"]: a for a in accounts if a.get("status") == "active"}
    usable_conns = [c for c in conns if c.get("status") == "active" and c.get("account_id") in active_accounts]
    if not usable_conns:
        return _err("UNAUTHORIZED", "No active GitHub authentication connection available for this operation.")

    # validate inputs
    if not isinstance(project_id, str) or re.match(r"^ghproj_[0-9A-Z]{18,}$", project_id) is None:
        c = usable_conns[0]
        return _log_resp(c["account_id"], c["id"], None, "create_task",
                         {"project_id": project_id, "mode": mode, "title": title, "body": body, "repository_full_name": repository_full_name, "field_values": field_values, "idempotency_key": idempotency_key},
                         _err("VALIDATION_ERROR", "Invalid project_id."), "failed", "Invalid project_id.")
    if not isinstance(mode, str) or mode not in ("draft", "issue"):
        c = usable_conns[0]
        return _log_resp(c["account_id"], c["id"], project_id, "create_task",
                         {"project_id": project_id, "mode": mode, "title": title, "body": body, "repository_full_name": repository_full_name, "field_values": field_values, "idempotency_key": idempotency_key},
                         _err("VALIDATION_ERROR", "Invalid mode; must be 'draft' or 'issue'."), "failed", "Invalid mode.")
    if not isinstance(title, str) or len(title) < 1:
        c = usable_conns[0]
        return _log_resp(c["account_id"], c["id"], project_id, "create_task",
                         {"project_id": project_id, "mode": mode, "title": title, "body": body, "repository_full_name": repository_full_name, "field_values": field_values, "idempotency_key": idempotency_key},
                         _err("VALIDATION_ERROR", "Invalid title."), "failed", "Invalid title.")
    if body is not None and not isinstance(body, str):
        c = usable_conns[0]
        return _log_resp(c["account_id"], c["id"], project_id, "create_task",
                         {"project_id": project_id, "mode": mode, "title": title, "body": body, "repository_full_name": repository_full_name, "field_values": field_values, "idempotency_key": idempotency_key},
                         _err("VALIDATION_ERROR", "body must be a string when provided."), "failed", "Invalid body.")

    proj = next((p for p in projects if p.get("id") == project_id), None)
    if not proj:
        c = usable_conns[0]
        return _log_resp(c["account_id"], c["id"], None, "create_task",
                         {"project_id": project_id, "mode": mode, "title": title, "body": body, "repository_full_name": repository_full_name, "field_values": field_values, "idempotency_key": idempotency_key},
                         _err("NOT_FOUND", "Project not found."), "failed", "Project not found.")
    if proj.get("account_id") not in active_accounts:
        c = usable_conns[0]
        return _log_resp(c["account_id"], c["id"], project_id, "create_task",
                         {"project_id": project_id, "mode": mode, "title": title, "body": body, "repository_full_name": repository_full_name, "field_values": field_values, "idempotency_key": idempotency_key},
                         _err("UNAUTHORIZED", "No active account context can access this project."), "failed", "Unauthorized.")
    conn = next((c for c in usable_conns if c.get("account_id") == proj.get("account_id")), None)
    if not conn:
        c = usable_conns[0]
        return _log_resp(c["account_id"], c["id"], project_id, "create_task",
                         {"project_id": project_id, "mode": mode, "title": title, "body": body, "repository_full_name": repository_full_name, "field_values": field_values, "idempotency_key": idempotency_key},
                         _err("UNAUTHORIZED", "No active auth connection for the project owner account."), "failed", "Unauthorized.")

    if mode == "issue":
        if not isinstance(repository_full_name, str) or re.match(r"^[^/]+/[^/]+$", repository_full_name) is None:
            return _log_resp(proj["account_id"], conn["id"], project_id, "create_task",
                             {"project_id": project_id, "mode": mode, "title": title, "body": body, "repository_full_name": repository_full_name, "field_values": field_values, "idempotency_key": idempotency_key},
                             _err("VALIDATION_ERROR", "repository_full_name must be provided as 'owner/repo' when mode='issue'."), "failed", "Invalid repository_full_name.")

    ok, ferr, emsg = _validate_field_values(project_id, field_values)
    if not ok:
        return _log_resp(proj["account_id"], conn["id"], project_id, "create_task",
                         {"project_id": project_id, "mode": mode, "title": title, "body": body, "repository_full_name": repository_full_name, "field_values": field_values, "idempotency_key": idempotency_key},
                         ferr, "failed", emsg)

    def _unique_item_node():
        node = "PVTI_" + "".join(random.choice(string.ascii_letters + string.digits) for _ in range(24))
        existing = {it.get("github_node_id") for it in items}
        while node in existing:
            node = "PVTI_" + "".join(random.choice(string.ascii_letters + string.digits) for _ in range(24))
        return node

    # Create
    if mode == "draft":
        item_row = {
            "id": _new_id("ghitem"),
            "project_id": project_id,
            "github_node_id": _unique_item_node(),
            "item_type": "draft",
            "content_github_node_id": None,
            "repository_full_name": None,
            "content_number": None,
            "draft_title": title,
            "draft_body": body,
            "field_values": field_values if field_values is not None else None,
            "position": None,
            "status": "active",
            "removed_at": None,
            "created_at": now,
            "updated_at": now,
        }
        items.append(item_row)
        _save("project_items.json", items)
        resp = {"item": item_row}
        return _log_resp(proj["account_id"], conn["id"], project_id, "create_task",
                         {"project_id": project_id, "mode": mode, "title": title, "body": body, "repository_full_name": repository_full_name, "field_values": field_values, "idempotency_key": idempotency_key},
                         resp, "succeeded")

    # mode == issue: simulate GitHub issue creation + add to project
    # create synthetic content node id and content number scoped to repo
    repo_items = [it for it in items if it.get("repository_full_name") == repository_full_name and it.get("content_number") is not None]
    next_num = 1
    if repo_items:
        try:
            next_num = max(int(it.get("content_number")) for it in repo_items) + 1
        except Exception:
            next_num = 1
    content_node_id = "ISSUE_" + "".join(random.choice(string.ascii_letters + string.digits) for _ in range(24))

    # derived uniqueness: unique(project_id, content_github_node_id) among active items
    for it in items:
        if it.get("project_id") == project_id and it.get("status") == "active" and it.get("content_github_node_id") == content_node_id:
            return _log_resp(proj["account_id"], conn["id"], project_id, "create_task",
                             {"project_id": project_id, "mode": mode, "title": title, "body": body, "repository_full_name": repository_full_name, "field_values": field_values, "idempotency_key": idempotency_key},
                             _err("CONFLICT", "Issue already exists in project (duplicate content)."), "failed", "Duplicate content in project.")

    item_row = {
        "id": _new_id("ghitem"),
        "project_id": project_id,
        "github_node_id": _unique_item_node(),
        "item_type": "issue",
        "content_github_node_id": content_node_id,
        "repository_full_name": repository_full_name,
        "content_number": next_num,
        "draft_title": None,
        "draft_body": None,
        "field_values": field_values if field_values is not None else None,
        "position": None,
        "status": "active",
        "removed_at": None,
        "created_at": now,
        "updated_at": now,
    }
    items.append(item_row)
    _save("project_items.json", items)

    resp = {"item": item_row}
    return _log_resp(proj["account_id"], conn["id"], project_id, "create_task",
                     {"project_id": project_id, "mode": mode, "title": title, "body": body, "repository_full_name": repository_full_name, "field_values": field_values, "idempotency_key": idempotency_key},
                     resp, "succeeded")

def get_current_identity(auth_connection_id, **_extra):
    import json, os, datetime, re, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0320000" if __import__("os").path.isdir("./environment_mix/0320000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _log(account_id=None, auth_id=None, request_payload=None, status="failed", error_message=None, response_payload=None):
        logs = _load("tool_action_logs.json")
        entry = {
            "id": _new_id("ghlog_"),
            "account_id": account_id or "unknown",
            "auth_connection_id": auth_id,
            "project_id": None,
            "tool_name": "get_current_identity",
            "request_payload": request_payload,
            "response_payload": response_payload,
            "github_request_ids": None,
            "idempotency_key": None,
            "status": status,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(entry)
        _save("tool_action_logs.json", logs)

    if not isinstance(auth_connection_id, str) or not re.match(r"^ghauth_[0-9A-Z]{18,}$", auth_connection_id):
        _log(auth_id=auth_connection_id, request_payload={"auth_connection_id": auth_connection_id}, status="failed", error_message="Invalid auth_connection_id.")
        return _err("VALIDATION_ERROR", "Invalid auth_connection_id.")

    accounts = _load("github_accounts.json")
    auths = _load("github_auth_connections.json")
    logs = _load("tool_action_logs.json")

    auth = next((a for a in auths if a.get("id") == auth_connection_id), None)
    if not auth:
        _log(auth_id=auth_connection_id, request_payload={"auth_connection_id": auth_connection_id}, status="failed", error_message="Auth connection not found.")
        return _err("NOT_FOUND", "Auth connection not found.")
    account = next((ac for ac in accounts if ac.get("id") == auth.get("account_id")), None)
    if not account:
        _log(account_id=auth.get("account_id") or "unknown", auth_id=auth_connection_id, request_payload={"auth_connection_id": auth_connection_id},
             status="failed", error_message="Account not found for auth connection.")
        return _err("NOT_FOUND", "Account not found for auth connection.")

    if auth.get("status") != "active":
        _log(account_id=account.get("id"), auth_id=auth_connection_id, request_payload={"auth_connection_id": auth_connection_id},
             status="failed", error_message="Auth connection is not active.")
        return _err("UNAUTHORIZED", "Auth connection is not active.", auth_status=auth.get("status"))
    if account.get("status") != "active":
        _log(account_id=account.get("id"), auth_id=auth_connection_id, request_payload={"auth_connection_id": auth_connection_id},
             status="failed", error_message="Account is disabled.")
        return _err("UNAUTHORIZED", "Account is disabled.")
    if not auth.get("token_ciphertext"):
        _log(account_id=account.get("id"), auth_id=auth_connection_id, request_payload={"auth_connection_id": auth_connection_id},
             status="failed", error_message="Auth connection has no token material.")
        return _err("UNAUTHORIZED", "Auth connection has no token material.")

    # Usage snapshot derived from tool_action_logs (since schema has no explicit rate-limit table)
    auth_logs = [l for l in logs if l.get("auth_connection_id") == auth_connection_id]
    total_calls = len(auth_logs)
    succeeded = sum(1 for l in auth_logs if l.get("status") == "succeeded")
    failed = sum(1 for l in auth_logs if l.get("status") == "failed")

    resp = {
        "account": {
            "id": account.get("id"),
            "github_node_id": account.get("github_node_id"),
            "login": account.get("login"),
            "account_type": account.get("account_type"),
            "status": account.get("status"),
            "created_at": account.get("created_at"),
            "updated_at": account.get("updated_at"),
        },
        "auth_connection": {
            "id": auth.get("id"),
            "auth_type": auth.get("auth_type"),
            "installation_id": auth.get("installation_id"),
            "scopes": auth.get("scopes"),
            "status": auth.get("status"),
            "token_expires_at": auth.get("token_expires_at"),
            "last_tested_at": auth.get("last_tested_at"),
            "last_error": auth.get("last_error"),
            "created_at": auth.get("created_at"),
            "updated_at": auth.get("updated_at"),
        },
        "usage": {
            "tool_calls_total": total_calls,
            "tool_calls_succeeded": succeeded,
            "tool_calls_failed": failed,
        },
        "meta": {"timestamp": now, "latency_ms": int((time.time() - t0) * 1000)},
    }

    _log(account_id=account.get("id"), auth_id=auth_connection_id, request_payload={"auth_connection_id": auth_connection_id},
         status="succeeded", response_payload={"account_id": account.get("id"), "auth_connection_id": auth_connection_id, "usage": resp["usage"]})
    return resp

def list_github_accounts(auth_connection_id, status=None, account_type=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0320000" if __import__("os").path.isdir("./environment_mix/0320000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        ts = int(datetime.datetime.utcnow().timestamp() * 1000)
        v = ts
        out = []
        while v > 0:
            v, r = divmod(v, 36)
            out.append(alphabet[r])
        s = "".join(reversed(out or ["0"]))
        s = (s + "0" * 18)[:18]
        return f"{prefix}_{s}"

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            if raw.startswith("idx:"):
                return int(raw.split(":", 1)[1])
            return 0
        except Exception:
            return 0

    def _encode_cursor(idx):
        raw = f"idx:{idx}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _log(account_id, auth_id, req, resp, ok, err_msg=None):
        logs = _load("tool_action_logs.json")
        logs.append({
            "id": _new_id("ghlog"),
            "account_id": account_id,
            "auth_connection_id": auth_id,
            "project_id": None,
            "tool_name": "list_github_accounts",
            "request_payload": req,
            "response_payload": resp,
            "github_request_ids": None,
            "idempotency_key": None,
            "status": "succeeded" if ok else "failed",
            "error_message": None if ok else (err_msg or "Request failed"),
            "created_at": now,
            "updated_at": now,
        })
        _save("tool_action_logs.json", logs)

    # Validate auth_connection_id and authenticate by id
    if not isinstance(auth_connection_id, str) or not re.match(r"^ghauth_[0-9A-Z]{18,}$", auth_connection_id):
        acct_id = (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "unknown")
        _log(acct_id, auth_connection_id, {"auth_connection_id": auth_connection_id, "status": status, "account_type": account_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor}, {"error": "validation"}, False, "auth_connection_id is malformed")
        return _err("VALIDATION_ERROR", "auth_connection_id is malformed", field="auth_connection_id")

    conns = _load("github_auth_connections.json")
    conn = next((c for c in conns if c.get("id") == auth_connection_id), None)
    if conn is None or conn.get("status") != "active":
        acct_id = conn.get("account_id") if conn else (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "unknown")
        _log(acct_id, auth_connection_id, {"auth_connection_id": auth_connection_id, "status": status, "account_type": account_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor}, {"error": "unauthorized"}, False, "Authentication is invalid or expired for this account")
        return _err("UNAUTHORIZED", "Authentication is invalid or expired for this account")

    # Validate filters
    if status is not None and (not isinstance(status, str) or status not in {"active", "disabled"}):
        _log(conn.get("account_id"), auth_connection_id, {"auth_connection_id": auth_connection_id, "status": status, "account_type": account_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor}, {"error": "validation"}, False, "status is invalid")
        return _err("VALIDATION_ERROR", "status is invalid", field="status")

    # Tool parameter uses "organization" but datastore uses "org"
    if account_type is not None:
        if not isinstance(account_type, str) or account_type not in {"user", "organization"}:
            _log(conn.get("account_id"), auth_connection_id, {"auth_connection_id": auth_connection_id, "status": status, "account_type": account_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor}, {"error": "validation"}, False, "account_type is invalid")
            return _err("VALIDATION_ERROR", "account_type is invalid", field="account_type")
        acct_type_store = "org" if account_type == "organization" else "user"
    else:
        acct_type_store = None

    if sort is not None and (not isinstance(sort, str) or sort not in {"created_at", "updated_at", "login"}):
        _log(conn.get("account_id"), auth_connection_id, {"auth_connection_id": auth_connection_id, "status": status, "account_type": account_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor}, {"error": "validation"}, False, "sort is invalid")
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")
    if order is not None and (not isinstance(order, str) or order not in {"asc", "desc"}):
        _log(conn.get("account_id"), auth_connection_id, {"auth_connection_id": auth_connection_id, "status": status, "account_type": account_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor}, {"error": "validation"}, False, "order is invalid")
        return _err("VALIDATION_ERROR", "order is invalid", field="order")

    if limit is None:
        limit_eff = 50
    elif not isinstance(limit, int):
        _log(conn.get("account_id"), auth_connection_id, {"auth_connection_id": auth_connection_id, "status": status, "account_type": account_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor}, {"error": "validation"}, False, "limit must be an integer")
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    else:
        limit_eff = max(1, min(100, limit))

    idx0 = _decode_cursor(cursor)
    if idx0 is None or idx0 < 0:
        _log(conn.get("account_id"), auth_connection_id, {"auth_connection_id": auth_connection_id, "status": status, "account_type": account_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor}, {"error": "validation"}, False, "cursor is invalid")
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    # Authorization scope: can only list accounts within connector; no additional forbidden logic in store, so allow.
    accounts = _load("github_accounts.json")
    rows = accounts[:]
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]
    if acct_type_store is not None:
        rows = [a for a in rows if a.get("account_type") == acct_type_store]

    reverse = (order or "asc") == "desc"
    sort_key = sort or "created_at"

    def _dt_or_min(s):
        if not isinstance(s, str):
            return datetime.datetime.min
        try:
            x = s[:-1] + "+00:00" if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return datetime.datetime.min

    if sort_key in ("created_at", "updated_at"):
        rows.sort(key=lambda r: (_dt_or_min(r.get(sort_key)), r.get("id") or ""), reverse=reverse)
    elif sort_key == "login":
        rows.sort(key=lambda r: ((r.get("login") or "").lower(), r.get("id") or ""), reverse=reverse)

    total = len(rows)
    page = rows[idx0: idx0 + limit_eff]
    next_idx = idx0 + len(page)
    has_more = next_idx < total
    next_cursor = _encode_cursor(next_idx) if has_more else None

    resp = {
        "accounts": page,
        "total": total,
        "limit": limit_eff,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "latency_ms": int((time.time() - t0) * 1000),
    }
    _log(conn.get("account_id"), auth_connection_id, {"auth_connection_id": auth_connection_id, "status": status, "account_type": account_type, "sort": sort, "order": order, "limit": limit, "cursor": cursor}, {"total": total, "returned": len(page), "has_more": has_more}, True)
    return resp

def update_github_account(account_id, status, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0320000" if __import__("os").path.isdir("./environment_mix/0320000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        raw = os.urandom(12)
        s = base64.b32encode(raw).decode("ascii").rstrip("=")
        return f"{prefix}_{s}"

    def _log(acct_id, ok, resp=None, err_msg=None):
        try:
            logs = _load("tool_action_logs.json")
            logs.append(
                {
                    "id": _new_id("ghlog"),
                    "account_id": acct_id if acct_id else "unknown",
                    "auth_connection_id": None,
                    "project_id": None,
                    "tool_name": "update_github_account",
                    "request_payload": {"account_id": account_id, "status": status},
                    "response_payload": resp,
                    "github_request_ids": None,
                    "idempotency_key": None,
                    "status": "succeeded" if ok else "failed",
                    "error_message": None if ok else (err_msg or "Request failed"),
                    "created_at": now,
                    "updated_at": now,
                }
            )
            _save("tool_action_logs.json", logs)
        except Exception:
            return

    try:
        if not isinstance(account_id, str) or not re.match(r"^ghacct_[0-9A-Z]{18,}$", account_id):
            resp = _err("VALIDATION_ERROR", "account_id is malformed", field="account_id")
            _log(None, False, resp, resp["error"]["message"])
            return resp
        if status not in ("active", "disabled"):
            resp = _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "disabled"])
            _log(account_id, False, resp, resp["error"]["message"])
            return resp

        accounts = _load("github_accounts.json")
        acct = next((a for a in accounts if a.get("id") == account_id), None)
        if not acct:
            resp = _err("NOT_FOUND", "GitHub account not found")
            _log(account_id, False, resp, resp["error"]["message"])
            return resp

        current = acct.get("status")
        if current == status:
            resp = _err("CONFLICT", "Requested status is already set")
            _log(account_id, False, resp, resp["error"]["message"])
            return resp

        allowed = {"active": ["disabled"], "disabled": ["active"]}
        if current not in allowed or status not in allowed[current]:
            resp = _err("INVALID_TRANSITION", "Illegal account status transition", from_status=current, to_status=status)
            _log(account_id, False, resp, resp["error"]["message"])
            return resp

        acct["status"] = status
        acct["updated_at"] = now
        _save("github_accounts.json", accounts)

        resp = {"account": acct}
        _log(account_id, True, {"account_id": acct.get("id"), "status": acct.get("status")})
        return resp
    except Exception as e:
        resp = _err("CONFLICT", "Unexpected server error", detail=str(e))
        _log(account_id if isinstance(account_id, str) else None, False, resp, resp["error"]["message"])
        return resp

def create_github_auth_connection(account_id, auth_type, access_token, installation_id=None, token_expires_at=None, scopes=None, test_on_create=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0320000" if __import__("os").path.isdir("./environment_mix/0320000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        raw = os.urandom(12)
        s = base64.b32encode(raw).decode("ascii").rstrip("=").upper()
        # ensure 18+ chars
        if len(s) < 18:
            s = (s + "0" * 18)[:18]
        return f"{prefix}_{s}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "INVALID"
        try:
            x = s[:-1] + "+00:00" if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return "INVALID"

    def _log(acct_id, auth_id, req, resp, ok, err_msg=None):
        logs = _load("tool_action_logs.json")
        logs.append({
            "id": _new_id("ghlog"),
            "account_id": acct_id,
            "auth_connection_id": auth_id,
            "project_id": None,
            "tool_name": "create_github_auth_connection",
            "request_payload": req,
            "response_payload": resp,
            "github_request_ids": None,
            "idempotency_key": None,
            "status": "succeeded" if ok else "failed",
            "error_message": None if ok else (err_msg or "Request failed"),
            "created_at": now,
            "updated_at": now,
        })
        _save("tool_action_logs.json", logs)

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^ghacct_[0-9A-Z]{18,}$", account_id):
        acct_for_log = (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "unknown")
        _log(acct_for_log, None, {"account_id": account_id, "auth_type": auth_type, "installation_id": installation_id, "access_token": "***redacted***" if isinstance(access_token, str) else access_token, "token_expires_at": token_expires_at, "scopes": scopes, "test_on_create": test_on_create}, {"error": "validation"}, False, "account_id is malformed")
        return _err("VALIDATION_ERROR", "account_id is malformed", field="account_id")

    if not isinstance(auth_type, str) or auth_type not in {"installation", "oauth"}:
        _log(account_id, None, {"account_id": account_id, "auth_type": auth_type, "installation_id": installation_id, "access_token": "***redacted***" if isinstance(access_token, str) else access_token, "token_expires_at": token_expires_at, "scopes": scopes, "test_on_create": test_on_create}, {"error": "validation"}, False, "auth_type is invalid")
        return _err("VALIDATION_ERROR", "auth_type is invalid", field="auth_type")

    if not isinstance(access_token, str) or not access_token.strip():
        _log(account_id, None, {"account_id": account_id, "auth_type": auth_type, "installation_id": installation_id, "access_token": "***redacted***" if isinstance(access_token, str) else access_token, "token_expires_at": token_expires_at, "scopes": scopes, "test_on_create": test_on_create}, {"error": "validation"}, False, "access_token is required")
        return _err("VALIDATION_ERROR", "access_token is required", field="access_token")

    if auth_type == "installation":
        if installation_id is None or not isinstance(installation_id, int) or installation_id < 1:
            _log(account_id, None, {"account_id": account_id, "auth_type": auth_type, "installation_id": installation_id, "access_token": "***redacted***", "token_expires_at": token_expires_at, "scopes": scopes, "test_on_create": test_on_create}, {"error": "validation"}, False, "installation_id is required for installation auth_type")
            return _err("VALIDATION_ERROR", "installation_id is required for installation auth_type", field="installation_id")
    else:
        if installation_id is not None and (not isinstance(installation_id, int) or installation_id < 1):
            _log(account_id, None, {"account_id": account_id, "auth_type": auth_type, "installation_id": installation_id, "access_token": "***redacted***", "token_expires_at": token_expires_at, "scopes": scopes, "test_on_create": test_on_create}, {"error": "validation"}, False, "installation_id must be a positive integer")
            return _err("VALIDATION_ERROR", "installation_id must be a positive integer", field="installation_id")

    exp_dt = _parse_dt(token_expires_at)
    if exp_dt == "INVALID":
        _log(account_id, None, {"account_id": account_id, "auth_type": auth_type, "installation_id": installation_id, "access_token": "***redacted***", "token_expires_at": token_expires_at, "scopes": scopes, "test_on_create": test_on_create}, {"error": "validation"}, False, "token_expires_at must be RFC3339 datetime")
        return _err("VALIDATION_ERROR", "token_expires_at must be RFC3339 datetime", field="token_expires_at")
    if exp_dt is not None and exp_dt <= now_dt.replace(tzinfo=datetime.timezone.utc):
        # allow but mark as expired per lifecycle rule; store anyway
        pass

    if scopes is not None:
        if not isinstance(scopes, list) or any((not isinstance(s, str) or not s.strip()) for s in scopes):
            _log(account_id, None, {"account_id": account_id, "auth_type": auth_type, "installation_id": installation_id, "access_token": "***redacted***", "token_expires_at": token_expires_at, "scopes": scopes, "test_on_create": test_on_create}, {"error": "validation"}, False, "scopes must be an array of non-empty strings")
            return _err("VALIDATION_ERROR", "scopes must be an array of non-empty strings", field="scopes")

    if test_on_create is not None and not isinstance(test_on_create, bool):
        _log(account_id, None, {"account_id": account_id, "auth_type": auth_type, "installation_id": installation_id, "access_token": "***redacted***", "token_expires_at": token_expires_at, "scopes": scopes, "test_on_create": test_on_create}, {"error": "validation"}, False, "test_on_create must be boolean")
        return _err("VALIDATION_ERROR", "test_on_create must be boolean", field="test_on_create")

    accounts = _load("github_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        _log(account_id, None, {"account_id": account_id, "auth_type": auth_type, "installation_id": installation_id, "access_token": "***redacted***", "token_expires_at": token_expires_at, "scopes": scopes, "test_on_create": test_on_create}, {"error": "not_found"}, False, "Account not found")
        return _err("NOT_FOUND", "Account not found", resource="github_accounts", id=account_id)

    # Map tool auth_type to store enum
    store_auth_type = "github_app_installation" if auth_type == "installation" else "oauth_user_token"
    store_install_id = installation_id if store_auth_type == "github_app_installation" else None

    conns = _load("github_auth_connections.json")
    # Enforce unique(account_id, auth_type, installation_id) by upsert-style idempotence
    existing = next((c for c in conns if c.get("account_id") == account_id and c.get("auth_type") == store_auth_type and c.get("installation_id") == store_install_id), None)

    # Token storage: must not authenticate by hash/ciphertext; we just store opaque ciphertext placeholder.
    token_ciphertext = "enc:" + base64.b64encode(access_token.encode("utf-8")).decode("ascii")

    status_val = "active"
    if exp_dt is not None:
        # store as Z if possible
        token_expires_z = exp_dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        if exp_dt <= now_dt.replace(tzinfo=datetime.timezone.utc):
            status_val = "expired"
    else:
        token_expires_z = None

    last_tested_at = None
    last_error = None

    if test_on_create:
        # Offline "test" = token exists and not empty -> succeed; if expired timestamp -> fail and mark expired
        if status_val == "active":
            last_tested_at = now
            last_error = None
        else:
            last_tested_at = now
            last_error = {"code": "expired", "message": "Token is expired."}

    if existing is not None:
        # Update existing row (legal transitions: disabled->active; expired->active allowed; revoked->disabled only; but we can set active/expired based on token)
        prior_status = existing.get("status")
        legal = {
            "active": {"expired", "revoked", "disabled"},
            "expired": {"active", "revoked", "disabled"},
            "revoked": {"disabled"},
            "disabled": {"active"},
        }
        if prior_status != status_val and prior_status in legal and status_val not in legal.get(prior_status, set()) and prior_status != status_val:
            # If transition illegal, keep prior status but still update token/material; do not pretend status changed
            status_to_set = prior_status
        else:
            status_to_set = status_val

        existing["token_ciphertext"] = token_ciphertext if status_to_set == "active" else existing.get("token_ciphertext") or token_ciphertext
        existing["token_expires_at"] = token_expires_z
        existing["scopes"] = scopes if scopes is not None else existing.get("scopes")
        existing["status"] = status_to_set
        existing["last_tested_at"] = last_tested_at if test_on_create else existing.get("last_tested_at")
        existing["last_error"] = last_error if test_on_create else existing.get("last_error")
        existing["updated_at"] = now
        _save("github_auth_connections.json", conns)
        resp = {"auth_connection": existing, "created": False, "latency_ms": int((time.time() - t0) * 1000)}
        _log(account_id, existing.get("id"), {"account_id": account_id, "auth_type": auth_type, "installation_id": installation_id, "access_token": "***redacted***", "token_expires_at": token_expires_at, "scopes": scopes, "test_on_create": test_on_create}, {"auth_connection_id": existing.get("id"), "created": False}, True)
        return resp

    # Insert new
    new_conn = {
        "id": _new_id("ghauth"),
        "account_id": account_id,
        "auth_type": store_auth_type,
        "installation_id": store_install_id,
        "token_ciphertext": token_ciphertext if status_val == "active" else token_ciphertext,
        "token_expires_at": token_expires_z,
        "scopes": scopes,
        "last_tested_at": last_tested_at,
        "last_error": last_error,
        "status": status_val,
        "created_at": now,
        "updated_at": now,
    }

    # Enforce constraint: status=active implies token_ciphertext not null (satisfied)
    conns.append(new_conn)
    _save("github_auth_connections.json", conns)

    resp = {"auth_connection": new_conn, "created": True, "latency_ms": int((time.time() - t0) * 1000)}
    _log(account_id, new_conn.get("id"), {"account_id": account_id, "auth_type": auth_type, "installation_id": installation_id, "access_token": "***redacted***", "token_expires_at": token_expires_at, "scopes": scopes, "test_on_create": test_on_create}, {"auth_connection_id": new_conn.get("id"), "created": True}, True)
    return resp

def update_github_auth_connection(auth_connection_id, status=None, access_token=None, token_expires_at=None, scopes=None, test_on_update=None, **_extra):
