            "id": _gen_id("tlog"),
            "account_id": acct_id,
            "auth_connection_id": auth_id,
            "project_id": None,
            "tool_name": "update_github_auth_connection",
            "request_payload": {
                "auth_connection_id": auth_connection_id,
