    # Validate inputs
    if not isinstance(auth_connection_id, str) or not re.match(r"^ghauth_[0-9A-Z]{18,}$", auth_connection_id):
        accs = _load("github_accounts.json")
        _log("failed", accs[0]["id"] if accs else "ghacct_UNKNOWN", auth_id=auth_connection_id, err="Invalid auth_connection_id")
        return _err("VALIDATION_ERROR", "Invalid auth_connection_id.")
    if status is not None and status not in ("active", "expired", "revoked", "disabled"):
        # log requires account_id; best-effort lookup
        conns = _load("github_auth_connections.json")
        c = next((x for x in conns if x.get("id") == auth_connection_id), None)
        acct_id = c.get("account_id") if c else (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "ghacct_UNKNOWN")
        _log("failed", acct_id, auth_id=auth_connection_id, err="Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status; must be one of: active, expired, revoked, disabled.")
    if access_token is not None and (not isinstance(access_token, str) or len(access_token) < 1):
        conns = _load("github_auth_connections.json")
        c = next((x for x in conns if x.get("id") == auth_connection_id), None)
        acct_id = c.get("account_id") if c else (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "ghacct_UNKNOWN")
        _log("failed", acct_id, auth_id=auth_connection_id, err="Invalid access_token")
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string when provided.")
    if scopes is not None:
        if not isinstance(scopes, list) or any((not isinstance(x, str) or not x) for x in scopes):
            conns = _load("github_auth_connections.json")
            c = next((x for x in conns if x.get("id") == auth_connection_id), None)
            acct_id = c.get("account_id") if c else (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "ghacct_UNKNOWN")
            _log("failed", acct_id, auth_id=auth_connection_id, err="Invalid scopes")
            return _err("VALIDATION_ERROR", "scopes must be an array of non-empty strings.")
    if test_on_update is not None and not isinstance(test_on_update, bool):
        conns = _load("github_auth_connections.json")
        c = next((x for x in conns if x.get("id") == auth_connection_id), None)
        acct_id = c.get("account_id") if c else (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "ghacct_UNKNOWN")
        _log("failed", acct_id, auth_id=auth_connection_id, err="Invalid test_on_update")
        return _err("VALIDATION_ERROR", "test_on_update must be a boolean.")

    dt_exp = _parse_dt(token_expires_at)
    if dt_exp == "INVALID":
        conns = _load("github_auth_connections.json")
        c = next((x for x in conns if x.get("id") == auth_connection_id), None)
        acct_id = c.get("account_id") if c else (_load("github_accounts.json")[0]["id"] if _load("github_accounts.json") else "ghacct_UNKNOWN")
        _log("failed", acct_id, auth_id=auth_connection_id, err="Invalid token_expires_at")
        return _err("VALIDATION_ERROR", "token_expires_at must be an ISO 8601 date-time string.")
    if isinstance(dt_exp, datetime.datetime) and dt_exp.tzinfo is None:
        dt_exp = dt_exp.replace(tzinfo=datetime.timezone.utc)

    # Load and find
    conns = _load("github_auth_connections.json")
    idx = next((i for i, c in enumerate(conns) if c.get("id") == auth_connection_id), None)
    if idx is None:
        accs = _load("github_accounts.json")
        _log("failed", accs[0]["id"] if accs else "ghacct_UNKNOWN", auth_id=auth_connection_id, err="Auth connection not found")
        return _err("NOT_FOUND", "Auth connection not found.")

    conn = conns[idx]
    acct_id = conn.get("account_id")

    # Apply lifecycle transition if requested
    if status is not None:
        cur = conn.get("status")
        if cur == status:
            _log("failed", acct_id, auth_id=auth_connection_id, err="Status already set")
            return _err("CONFLICT", "Requested status is already set on the auth connection.")
        transitions = {
            "active": ["expired", "revoked", "disabled"],
            "expired": ["active", "revoked", "disabled"],
            "revoked": ["disabled"],
            "disabled": ["active"],
        }
        if cur not in transitions or status not in transitions[cur]:
            _log("failed", acct_id, auth_id=auth_connection_id, err="Invalid transition")
            return _err("INVALID_TRANSITION", f"Cannot transition auth connection from {cur} to {status}.")
        conn["status"] = status

    # Rotation: if any rotation-related fields are provided, require access_token present
    rotation_fields_provided = (access_token is not None) or (token_expires_at is not None) or (scopes is not None)
    if rotation_fields_provided and access_token is None:
        _log("failed", acct_id, auth_id=auth_connection_id, err="Missing access_token for rotation")
        return _err("VALIDATION_ERROR", "access_token is required when rotating credentials (token_expires_at/scopes/access_token).")

    if access_token is not None:
        conn["token_ciphertext"] = "enc:" + hashlib.sha256(access_token.encode("utf-8")).hexdigest()
        conn["last_error"] = None  # reset on rotation
        # Note: do not force status to active; unless test_on_update implies it
    if token_expires_at is not None:
        conn["token_expires_at"] = (dt_exp.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z") if isinstance(dt_exp, datetime.datetime) else None)
    if scopes is not None:
        # only meaningful for oauth_user_token, but accept and store for completeness
        conn["scopes"] = scopes

    # Enforce constraint: auth_type=github_app_installation implies installation_id not null
    if conn.get("auth_type") == "github_app_installation" and conn.get("installation_id") is None:
        _log("failed", acct_id, auth_id=auth_connection_id, err="installation_id required by auth_type")
        return _err("VALIDATION_ERROR", "installation_id is required for github_app_installation auth connections.")
    # Enforce constraint: status=active implies token_ciphertext not null
    if conn.get("status") == "active" and not conn.get("token_ciphertext"):
        _log("failed", acct_id, auth_id=auth_connection_id, err="Active requires token_ciphertext")
        return _err("VALIDATION_ERROR", "Active auth connection requires stored token.")

    # Enforce token_expires_at must be null or > created_at
    created_at = conn.get("created_at")
    if isinstance(created_at, str):
        try:
            ca = created_at
            if ca.endswith("Z"):
                ca = ca[:-1] + "+00:00"
            ca_dt = datetime.datetime.fromisoformat(ca)
            if ca_dt.tzinfo is None:
                ca_dt = ca_dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            ca_dt = None
    else:
        ca_dt = None
    if isinstance(dt_exp, datetime.datetime) and ca_dt is not None:
        if dt_exp <= ca_dt:
            _log("failed", acct_id, auth_id=auth_connection_id, err="token_expires_at must be > created_at")
            return _err("VALIDATION_ERROR", "token_expires_at must be later than creation time.")

    # Optional test semantics after update
    if test_on_update:
        conn["last_tested_at"] = now
        # Offline heuristic similar to create:
        exp_dt = None
        if isinstance(conn.get("token_expires_at"), str):
            exp_raw = conn["token_expires_at"]
            try:
                x = exp_raw[:-1] + "+00:00" if exp_raw.endswith("Z") else exp_raw
                exp_dt = datetime.datetime.fromisoformat(x)
                if exp_dt.tzinfo is None:
                    exp_dt = exp_dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                exp_dt = None

        if exp_dt is not None and exp_dt <= datetime.datetime.now(datetime.timezone.utc):
            conn["status"] = "expired"
            conn["last_error"] = {"code": "TOKEN_EXPIRED", "message": "Token is expired."}
        else:
            # if we just rotated with a token containing 'revoked', mark revoked
            if isinstance(access_token, str) and "revoked" in access_token.lower():
                conn["status"] = "revoked"
                conn["last_error"] = {"code": "TOKEN_REVOKED", "message": "Token appears revoked."}
            else:
                conn["status"] = "active"
                conn["last_error"] = None

    conn["updated_at"] = now
    conns[idx] = conn
    _save("github_auth_connections.json", conns)

    _log("succeeded", acct_id, auth_id=auth_connection_id, resp={"auth_connection_id": auth_connection_id, "status": conn.get("status")})
    return {"auth_connection": conn}

def get_project(project_id, auth_connection_id=None, refresh=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0320000" if __import__("os").path.isdir("./environment_mix/0320000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        s = uuid.uuid4().hex.upper()
        s = re.sub(r"[^0-9A-Z]", "", s)
        return f"{prefix}_{s[:20]}"

    t0 = time.time()
    logs = _load("tool_action_logs.json")
    accounts = _load("github_accounts.json")
    auths = _load("github_auth_connections.json")
    projects = _load("projects.json")

    log_entry = {
        "id": _new_id("ghlog"),
        "account_id": None,
        "auth_connection_id": auth_connection_id,
        "project_id": project_id,
        "tool_name": "get_project",
        "request_payload": {"project_id": project_id, "auth_connection_id": auth_connection_id, "refresh": refresh},
        "response_payload": None,
        "github_request_ids": None,
        "idempotency_key": None,
        "status": "failed",
        "error_message": None,
        "created_at": _now(),
        "updated_at": _now(),
    }

    def _finish_ok(account_id, auth_id, project_row, refreshed):
        log_entry["account_id"] = account_id
        log_entry["auth_connection_id"] = auth_id
        log_entry["status"] = "succeeded"
        log_entry["error_message"] = None
        log_entry["updated_at"] = _now()
        log_entry["response_payload"] = {
            "project_id": project_row.get("id"),
            "status": project_row.get("status"),
            "refreshed": bool(refreshed),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(log_entry)
        _save("tool_action_logs.json", logs)
        return {
            "project": project_row,
            "refreshed": bool(refreshed),
        }

    def _finish_err(code, msg, account_id=None, auth_id=None, **extra):
        log_entry["account_id"] = account_id or (accounts[0].get("id") if accounts else "unknown")
        log_entry["auth_connection_id"] = auth_id
        log_entry["status"] = "failed"
        log_entry["error_message"] = msg
        log_entry["updated_at"] = _now()
        log_entry["response_payload"] = {"error": {"code": code, "message": msg, **extra}, "latency_ms": int((time.time() - t0) * 1000)}
        logs.append(log_entry)
        _save("tool_action_logs.json", logs)
        return _err(code, msg, **extra)

    if not isinstance(project_id, str) or not re.match(r"^ghproj_[0-9A-Z]{18,}$", project_id):
        return _finish_err("VALIDATION_ERROR", "project_id is malformed", field="project_id")

    project = next((p for p in projects if p.get("id") == project_id), None)
    if project is None:
        return _finish_err("NOT_FOUND", "Project not found", resource="projects", id=project_id)

    account_id = project.get("account_id")

    # If auth_connection_id provided, authenticate by id (not ciphertext); if not provided, resolve any active conn for the account.
    auth_row = None
    if auth_connection_id is not None:
        if not isinstance(auth_connection_id, str) or not re.match(r"^ghauth_[0-9A-Z]{18,}$", auth_connection_id):
            return _finish_err("VALIDATION_ERROR", "auth_connection_id is malformed", account_id=account_id, field="auth_connection_id")
        auth_row = next((a for a in auths if a.get("id") == auth_connection_id), None)
        if auth_row is None or auth_row.get("account_id") != account_id or auth_row.get("status") != "active":
            return _finish_err("UNAUTHORIZED", "Authentication is invalid or expired for this account.", account_id=account_id)
    else:
        auth_row = next((a for a in auths if a.get("account_id") == account_id and a.get("status") == "active"), None)

    refreshed = False
    if refresh:
        # offline: no GitHub fetch; treat as no-op but mark refreshed flag to indicate request honored
        refreshed = True
        project["updated_at"] = _now()
        _save("projects.json", projects)

    return _finish_ok(account_id, auth_row.get("id") if auth_row else None, project, refreshed)
